hovers.expr:
let a := dist p₁ p₂;
let b := dist p₃ p₂;
let c := dist p₁ p₃;
let s := (a + b + c) / 2;
1 / 2 * a * b * sin (∠ p₁ p₂ p₃) = √(s * (s - a) * (s - b) * (s - c))

let b := dist p₃ p₂;
let c := dist p₁ p₃;
let s := (a + b + c) / 2;
1 / 2 * a * b * sin (∠ p₁ p₂ p₃) = √(s * (s - a) * (s - b) * (s - c))

let c := dist p₁ p₃;
let s := (a + b + c) / 2;
1 / 2 * a * b * sin (∠ p₁ p₂ p₃) = √(s * (s - a) * (s - b) * (s - c))

hovers.type:
∀ {V : Type u_1} {P : Type u_2} [inst : NormedAddCommGroup V] [inst_1 : InnerProductSpace ℝ V] [inst_2 : MetricSpace P]
  [inst_3 : NormedAddTorsor V P] {p₁ p₂ p₃ : P},
  p₁ ≠ p₂ →
    p₃ ≠ p₂ →
      have a := dist p₁ p₂;
      have b := dist p₃ p₂;
      have c := dist p₁ p₃;
      have s := (a + b + c) / 2;
      1 / 2 * a * b * sin (∠ p₁ p₂ p₃) = √(s * (s - a) * (s - b) * (s - c))

